"""Module for test control CLI"""
import argparse
from pathlib import Path

from marvin_client import MarvinClient
from marvin_client.cli.test_control import validations
from marvin_client.exceptions import UnsupportedCommand
from marvin_client import utils


class TestControlCli:
    __test__ = False  # for pytest to not warn about this class (name starts with "Test")

    def __init__(self, args: argparse.Namespace, marvin_client: MarvinClient) -> None:
        """
        Constructor.
        :param args: Parsed arguments
        :param marvin_client Marvin client
        """
        self._args = args
        self._marvin_client = marvin_client

    @staticmethod
    def create_arguments(arg_parser: argparse.ArgumentParser) -> None:
        """Create arguments to domain specific argument parser"""
        # 1st positional argument "command"
        arg_parser.add_argument(
            "command",
            choices=["create", "update", "start", "stop"],
            type=str.lower,
            help="Test control command",
        )
        # --data argument
        arg_parser.add_argument(
            "--data",
            metavar="JSON",
            action="append",
            help="Object data as JSON string",
        )
        # --file-data argument
        arg_parser.add_argument(
            "--file-data",
            metavar="FILE",
            type=Path,
            action="append",
            help="Object data as JSON file",
        )
        # --skip-merge argument for update command
        arg_parser.add_argument(
            "--skip-merge",
            action="store_true",
            help="Skip merging objects for update command",
        )

    @staticmethod
    def validate_arguments(arg_parser: argparse.ArgumentParser, args: argparse.Namespace) -> None:
        """
        Validate command line arguments after they are parsed.

        Custom validations which are not caught by the `ArgumentParser` can be implemented here.
        In case validation fails, call `arg_parser.error("<message>")` to exit the command line tool.

        :param arg_parser: Argument parser
        :param args: Parsed arguments
        """
        # Validate that at least one of "--data" or "--file-data" is set
        if not args.data and not args.file_data:
            arg_parser.error("Argument '--data' or '--file-data' is missing")

    def process_command(self) -> None:
        """Process command"""
        # Read object data from arguments '--data' and '--file-data'
        objects_data = self._read_object_data()

        # Merge object data for update operation
        if self._args.command == "update" and len(objects_data) > 1 and not self._args.skip_merge:
            objects_data = self._merge_objects(objects_data)

        # Call command handler method for each data object
        for obj_data in objects_data:
            object_type = validations.validate_object_type(self._args.command, obj_data)

            # Get command handler method name "_process_<command>_<object_type>()",
            # e.g. "_process_create_test_run()"
            cmd_handler_name = f"_process_{self._args.command}_{object_type}"
            command_handler = getattr(self, cmd_handler_name, None)
            if not command_handler:
                raise UnsupportedCommand(f"Command handler not implemented: {cmd_handler_name}()")

            command_handler(obj_data)

    def _read_object_data(self) -> list[dict]:
        """
        Process command line arguments '--data' and '--file-data'.

        :return: List of data objects
        """
        data_objects: list[dict] = []

        # Validate JSON data from '--data' (a list)
        if self._args.data:
            for json_data in self._args.data:
                obj_data = validations.validate_json_data(json_data)
                data_objects.append(obj_data)

        # Validate JSON data from '--file-data' (a list)
        if self._args.file_data:
            file: Path
            for file in self._args.file_data:
                if file.is_dir():
                    # File path is a folder. Read all .json files from it. Put them in ascending order.
                    json_files = [json_file for json_file in file.glob("*.json")]
                    json_files.sort()
                    for json_file in json_files:
                        obj_data = validations.validate_json_file(json_file)
                        data_objects.append(obj_data)
                else:
                    # File path is a single JSON file
                    obj_data = validations.validate_json_file(file)
                    data_objects.append(obj_data)

        return data_objects

    def _merge_objects(self, objects_data: list[dict]) -> list[dict]:
        """
        Merge objects data.
        Objects representing the same object type and instance (IDs) are merged together.
        The target object where others are merged is the first one found in the list.

        :param objects_data: Objects to merge
            Example object data structure:
            {
                "meta": {},
                "test_run": {}
            }
        :return: Merged objects data
        """
        merged_data = {}  # Key: unique object ID as string, Value: object data

        for obj_data in objects_data:
            obj_type = validations.validate_object_type(self._args.command, obj_data)

            meta = obj_data["meta"]
            obj_key = "{}_{}_{}_{}".format(meta["bts_id"], meta.get("run_id"), meta.get("case_id"), meta.get("step_id"))

            if obj_key not in merged_data:
                merged_data[obj_key] = obj_data
            else:
                utils.merge_dicts(merged_data[obj_key][obj_type], obj_data[obj_type])

        return list(merged_data.values())

    def _process_create_test_run(self, obj_data: dict) -> None:
        """
        Create test run.

        :param obj_data: Object data. E.g.
            {
                "meta": {
                    "run_id": "32ae8de7-f6c7-44f5-9e59-4ebf0552d9e6"
                },
                "test_run": {
                    "id": "32ae8de7-f6c7-44f5-9e59-4ebf0552d9e6",
                    ...
                }
            }
        """
        assert self._marvin_client

        bts_id = obj_data["meta"]["bts_id"]

        self._marvin_client.test_control.create_test_run(bts_id, obj_data["test_run"])

