    def _process_start_test_run(self, obj_data: dict) -> None:
        """
        Start test run.

        :param obj_data: Object data. E.g.
            {
                "meta": {
                    "run_id": "32ae8de7-f6c7-44f5-9e59-4ebf0552d9e6"
                },
                "test_run": {
                    "start_time": "2023-08-29T17:01:05.123456Z"
                }
            }
        """
        assert self._marvin_client

        bts_id = obj_data["meta"]["bts_id"]
        run_id = obj_data["meta"]["run_id"]
        start_time = None

        test_run = obj_data.get("test_run")
        if test_run:
            start_time = test_run.get("start_time")

        validations.validate_not_empty(run_id, "meta.run_id")

        if start_time:
            validations.validate_datetime_str(start_time, "test_run.start_time")

        self._marvin_client.test_control.start_test_run(bts_id, run_id, start_time)

